-- DT-REL-STORAGE-01: constrain ordinary writes; no bucket or object changes.
-- Public visibility remains unchanged for the separate G07-A intervention.
CREATE POLICY rel_storage01_media_insert ON public.experience_media AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK ((EXISTS (SELECT 1 FROM public.experiences e JOIN public.operator_memberships m ON m.operator_id=e.operator_id WHERE e.id=experience_media.experience_id AND NOT e.published AND e.review_status IN ('draft','rejected') AND m.user_id=(SELECT auth.uid()) AND m.role IN ('owner','manager'))) AND (EXISTS (SELECT 1 FROM public.experiences e WHERE e.id=experience_media.experience_id AND split_part(experience_media.storage_path,'/',1)=e.operator_id::text AND split_part(experience_media.storage_path,'/',2)=e.id::text AND split_part(experience_media.storage_path,'/',3)<>'' AND array_length(string_to_array(experience_media.storage_path,'/'),1)=3)));
CREATE POLICY rel_storage01_media_update ON public.experience_media AS RESTRICTIVE FOR UPDATE TO authenticated USING (EXISTS (SELECT 1 FROM public.experiences e JOIN public.operator_memberships m ON m.operator_id=e.operator_id WHERE e.id=experience_media.experience_id AND NOT e.published AND e.review_status IN ('draft','rejected') AND m.user_id=(SELECT auth.uid()) AND m.role IN ('owner','manager'))) WITH CHECK ((EXISTS (SELECT 1 FROM public.experiences e JOIN public.operator_memberships m ON m.operator_id=e.operator_id WHERE e.id=experience_media.experience_id AND NOT e.published AND e.review_status IN ('draft','rejected') AND m.user_id=(SELECT auth.uid()) AND m.role IN ('owner','manager'))) AND (EXISTS (SELECT 1 FROM public.experiences e WHERE e.id=experience_media.experience_id AND split_part(experience_media.storage_path,'/',1)=e.operator_id::text AND split_part(experience_media.storage_path,'/',2)=e.id::text AND split_part(experience_media.storage_path,'/',3)<>'' AND array_length(string_to_array(experience_media.storage_path,'/'),1)=3)));
CREATE POLICY rel_storage01_media_delete ON public.experience_media AS RESTRICTIVE FOR DELETE TO authenticated USING (EXISTS (SELECT 1 FROM public.experiences e JOIN public.operator_memberships m ON m.operator_id=e.operator_id WHERE e.id=experience_media.experience_id AND NOT e.published AND e.review_status IN ('draft','rejected') AND m.user_id=(SELECT auth.uid()) AND m.role IN ('owner','manager')));
CREATE POLICY rel_storage01_object_insert ON storage.objects AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK (((bucket_id IS DISTINCT FROM 'experience-media' OR (EXISTS (SELECT 1 FROM public.experiences e JOIN public.operator_memberships m ON m.operator_id=e.operator_id WHERE e.id::text=split_part(objects.name,'/',2) AND e.operator_id::text=split_part(objects.name,'/',1) AND NOT e.published AND e.review_status IN ('draft','rejected') AND m.user_id=(SELECT auth.uid()) AND m.role IN ('owner','manager')) AND split_part(objects.name,'/',3)<>'' AND array_length(string_to_array(objects.name,'/'),1)=3 AND NOT EXISTS (SELECT 1 FROM public.experience_media em JOIN public.experiences e ON e.id=em.experience_id WHERE em.storage_path=objects.name AND (e.published OR e.review_status NOT IN ('draft','rejected'))))) AND (bucket_id IS DISTINCT FROM 'experience-revision-media' OR (EXISTS (SELECT 1 FROM public.experience_revisions r JOIN public.operator_memberships m ON m.operator_id=r.operator_id WHERE r.id::text=split_part(objects.name,'/',3) AND r.operator_id::text=split_part(objects.name,'/',1) AND split_part(objects.name,'/',2)='revisions' AND split_part(objects.name,'/',4)<>'' AND array_length(string_to_array(objects.name,'/'),1)=4 AND r.status IN ('draft','rejected') AND m.user_id=(SELECT auth.uid()) AND m.role IN ('owner','manager'))))));
CREATE POLICY rel_storage01_object_update ON storage.objects AS RESTRICTIVE FOR UPDATE TO authenticated USING (((bucket_id IS DISTINCT FROM 'experience-media' OR (EXISTS (SELECT 1 FROM public.experiences e JOIN public.operator_memberships m ON m.operator_id=e.operator_id WHERE e.id::text=split_part(objects.name,'/',2) AND e.operator_id::text=split_part(objects.name,'/',1) AND NOT e.published AND e.review_status IN ('draft','rejected') AND m.user_id=(SELECT auth.uid()) AND m.role IN ('owner','manager')) AND split_part(objects.name,'/',3)<>'' AND array_length(string_to_array(objects.name,'/'),1)=3 AND NOT EXISTS (SELECT 1 FROM public.experience_media em JOIN public.experiences e ON e.id=em.experience_id WHERE em.storage_path=objects.name AND (e.published OR e.review_status NOT IN ('draft','rejected'))))) AND (bucket_id IS DISTINCT FROM 'experience-revision-media' OR (EXISTS (SELECT 1 FROM public.experience_revisions r JOIN public.operator_memberships m ON m.operator_id=r.operator_id WHERE r.id::text=split_part(objects.name,'/',3) AND r.operator_id::text=split_part(objects.name,'/',1) AND split_part(objects.name,'/',2)='revisions' AND split_part(objects.name,'/',4)<>'' AND array_length(string_to_array(objects.name,'/'),1)=4 AND r.status IN ('draft','rejected') AND m.user_id=(SELECT auth.uid()) AND m.role IN ('owner','manager')))))) WITH CHECK (((bucket_id IS DISTINCT FROM 'experience-media' OR (EXISTS (SELECT 1 FROM public.experiences e JOIN public.operator_memberships m ON m.operator_id=e.operator_id WHERE e.id::text=split_part(objects.name,'/',2) AND e.operator_id::text=split_part(objects.name,'/',1) AND NOT e.published AND e.review_status IN ('draft','rejected') AND m.user_id=(SELECT auth.uid()) AND m.role IN ('owner','manager')) AND split_part(objects.name,'/',3)<>'' AND array_length(string_to_array(objects.name,'/'),1)=3 AND NOT EXISTS (SELECT 1 FROM public.experience_media em JOIN public.experiences e ON e.id=em.experience_id WHERE em.storage_path=objects.name AND (e.published OR e.review_status NOT IN ('draft','rejected'))))) AND (bucket_id IS DISTINCT FROM 'experience-revision-media' OR (EXISTS (SELECT 1 FROM public.experience_revisions r JOIN public.operator_memberships m ON m.operator_id=r.operator_id WHERE r.id::text=split_part(objects.name,'/',3) AND r.operator_id::text=split_part(objects.name,'/',1) AND split_part(objects.name,'/',2)='revisions' AND split_part(objects.name,'/',4)<>'' AND array_length(string_to_array(objects.name,'/'),1)=4 AND r.status IN ('draft','rejected') AND m.user_id=(SELECT auth.uid()) AND m.role IN ('owner','manager'))))));
CREATE POLICY rel_storage01_object_delete ON storage.objects AS RESTRICTIVE FOR DELETE TO authenticated USING (((bucket_id IS DISTINCT FROM 'experience-media' OR (EXISTS (SELECT 1 FROM public.experiences e JOIN public.operator_memberships m ON m.operator_id=e.operator_id WHERE e.id::text=split_part(objects.name,'/',2) AND e.operator_id::text=split_part(objects.name,'/',1) AND NOT e.published AND e.review_status IN ('draft','rejected') AND m.user_id=(SELECT auth.uid()) AND m.role IN ('owner','manager')) AND split_part(objects.name,'/',3)<>'' AND array_length(string_to_array(objects.name,'/'),1)=3 AND NOT EXISTS (SELECT 1 FROM public.experience_media em JOIN public.experiences e ON e.id=em.experience_id WHERE em.storage_path=objects.name AND (e.published OR e.review_status NOT IN ('draft','rejected'))))) AND (bucket_id IS DISTINCT FROM 'experience-revision-media' OR (EXISTS (SELECT 1 FROM public.experience_revisions r JOIN public.operator_memberships m ON m.operator_id=r.operator_id WHERE r.id::text=split_part(objects.name,'/',3) AND r.operator_id::text=split_part(objects.name,'/',1) AND split_part(objects.name,'/',2)='revisions' AND split_part(objects.name,'/',4)<>'' AND array_length(string_to_array(objects.name,'/'),1)=4 AND r.status IN ('draft','rejected') AND m.user_id=(SELECT auth.uid()) AND m.role IN ('owner','manager'))))));
